<script setup lang="ts">
definePageMeta({layout:'admin',middleware:'admin'})
const search=ref(''),status=ref('all'),mode=ref<'list'|'day'|'week'>('list')
const remoteFilters=computed(()=>({q:search.value,status:status.value}))
const {data,refresh,pending,error:fetchError}=await useFetch<any[]>('/api/admin/appointments',{query:remoteFilters})
const {data:config}=await useFetch<any>('/api/admin/settings')
const selectedDate=ref(''),calendar=ref(false)
const editing=ref<any>(null),newDate=ref(''),newTime=ref(''),working=ref(false),error=ref(''),notice=ref('')
const todayIso=()=>{const parts=new Intl.DateTimeFormat('en-US',{timeZone:config.value?.timezone||'Asia/Tehran',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const p=(n:string)=>parts.find(x=>x.type===n)?.value||'';return `${p('year')}-${p('month')}-${p('day')}`} 
onMounted(()=>selectedDate.value=todayIso())
const statuses=[{value:'all',label:'همه وضعیت‌ها'},{value:'confirmed',label:'تأییدشده'},{value:'completed',label:'انجام‌شده'},{value:'cancelled',label:'لغوشده'},{value:'no_show',label:'عدم مراجعه'}]
const label=(s:string)=>statuses.find(a=>a.value===s)?.label||s
const visible=computed(()=>{
  let rows=(data.value||[]).filter(a=>(status.value==='all'||a.status===status.value)&&`${a.patient_name} ${a.mobile} ${a.tracking_code} ${a.service}`.includes(search.value))
  if(mode.value==='day'&&selectedDate.value)rows=rows.filter(a=>a.date===selectedDate.value)
  if(mode.value==='week'&&selectedDate.value){const d=new Date(`${selectedDate.value}T12:00:00Z`);const diff=(d.getUTCDay()+1)%7;const start=new Date(d.getTime()-diff*86400000).toISOString().slice(0,10);const end=new Date(d.getTime()+(6-diff)*86400000).toISOString().slice(0,10);rows=rows.filter(a=>a.date>=start&&a.date<=end)}
  return rows.sort((a,b)=>b.start_at.localeCompare(a.start_at))
})
const weekDays=computed(()=>{
  if(!selectedDate.value)return []
  const d=new Date(`${selectedDate.value}T12:00:00Z`)
  const offset=(d.getUTCDay()+1)%7
  return Array.from({length:7},(_,i)=>new Date(d.getTime()+(i-offset)*86400000).toISOString().slice(0,10))
})
const weekNames=['شنبه','یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه','جمعه']
const weekMap=computed(()=>weekDays.value.map((day,i)=>({day,name:weekNames[i],appointments:visible.value.filter(a=>a.date===day).sort((a,b)=>a.time.localeCompare(b.time))})))
async function changeStatus(a:any,st:string){error.value='';notice.value='';working.value=true;try{await $fetch(`/api/admin/appointments/${a.id}`,{method:'PATCH',body:{status:st}});await refresh();notice.value='وضعیت نوبت به‌روزرسانی شد.'}catch(e){error.value=humanError(e)}finally{working.value=false}}
async function saveTime(){if(!editing.value||!newDate.value||!newTime.value)return;error.value='';working.value=true;try{await $fetch(`/api/admin/appointments/${editing.value.id}`,{method:'PATCH',body:{date:newDate.value,time:newTime.value,status:'confirmed'}});editing.value=null;await refresh();notice.value='زمان نوبت تغییر کرد.'}catch(e){error.value=humanError(e)}finally{working.value=false}}
function edit(a:any){editing.value=a;newDate.value=a.date;newTime.value=a.time;error.value='';notice.value=''}
useSeoMeta({title:'مدیریت نوبت‌ها | پنل مدیریت',robots:'noindex,nofollow'})
</script>
<template><div><div class="flex justify-between flex-wrap gap-4 items-center mb-8"><div><span class="eyebrow">برنامه‌ریزی بیماران</span><h1 class="text-3xl font-extrabold text-jade-800 mt-2">مدیریت نوبت‌ها</h1></div><button class="btn-light" @click="refresh"><Icon name="refresh-ccw" :size="17" /> به‌روزرسانی</button></div><div class="glass-card p-5 mb-5 flex gap-3 flex-col md:flex-row"><div class="relative flex-1"><Icon name="search" :size="17" class="absolute top-3.5 right-3 text-[#8ca69a]" /><input v-model="search" class="input-field !pr-10" placeholder="جستجوی بیمار، موبایل، خدمت یا کد پیگیری..." /></div><select v-model="status" class="input-field md:!w-[190px]"><option v-for="s in statuses" :key="s.value" :value="s.value">{{s.label}}</option></select><select v-model="mode" class="input-field md:!w-[165px]"><option value="list">همه نوبت‌ها</option><option value="day">نمای روزانه</option><option value="week">نمای هفتگی</option></select><button v-if="mode!=='list'" class="btn-light shrink-0" @click="calendar=!calendar"><Icon name="calendar-days" :size="17" />{{selectedDate?faDate(selectedDate):'انتخاب تاریخ'}}</button></div><div v-if="calendar&&mode!=='list'" class="glass-card p-5 max-w-[380px] mb-5"><JalaliCalendar v-model="selectedDate" :horizon="365" allow-past /></div><p v-if="error" role="alert" class="p-4 bg-red-50 text-red-700 rounded-xl text-xs mb-5">{{error}}</p><p v-if="notice" class="p-4 bg-green-50 text-green-700 rounded-xl text-xs mb-5">{{notice}}</p><div v-if="mode==='week'" class="grid grid-cols-2 sm:grid-cols-4 xl:grid-cols-7 gap-3 mb-6"><div v-for="day in weekMap" :key="day.day" class="glass-card min-h-[145px] p-3"><p class="text-xs font-extrabold text-jade-800">{{day.name}}</p><p class="text-[10px] text-[#91a89c] mt-1 mb-3">{{faDate(day.day)}}</p><div v-for="a in day.appointments" :key="a.id" class="bg-[#eef7f0] rounded-lg p-2 mb-2 text-[10px] text-jade-800"><strong class="block" dir="ltr">{{a.time}}</strong><span class="block mt-1 truncate">{{a.patient_name}}</span></div><p v-if="!day.appointments.length" class="text-[10px] text-[#a0b1a5] mt-5">نوبتی نیست</p></div></div><div class="glass-card overflow-hidden"><div class="flex justify-between items-center p-6"><h2 class="text-sm font-bold">فهرست نوبت‌ها</h2><span class="text-xs text-[#91a79a]">{{faNumber(visible.length)}} نوبت</span></div><div class="overflow-x-auto"><table class="admin-table"><thead><tr><th>بیمار</th><th>خدمت</th><th>تاریخ / ساعت</th><th>موبایل</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody><tr v-for="a in visible" :key="a.id"><td><span class="font-bold block">{{a.patient_name}}</span><span class="text-[10px] text-[#8aa399]" dir="ltr">{{a.tracking_code}}</span></td><td>{{a.service}}</td><td><span class="block whitespace-nowrap">{{faDate(a.date)}}</span><span class="text-[#83a394]" dir="ltr">{{a.time}}</span></td><td dir="ltr">{{a.mobile}}</td><td><select :value="a.status" :disabled="working" class="bg-transparent text-[11px] rounded-lg border border-[#dae7de] p-2" @change="changeStatus(a,($event.target as HTMLSelectElement).value)"><option v-for="s in statuses.filter(s=>s.value!=='all')" :key="s.value" :value="s.value">{{s.label}}</option></select></td><td><button class="text-jade-700 rounded-lg bg-jade-50 p-2" title="جابه‌جایی" @click="edit(a)"><Icon name="calendar-clock" :size="17" /></button></td></tr><tr v-if="!visible.length"><td colspan="6" class="!text-center !py-14">{{fetchError?'خطا در دریافت نوبت‌ها.':'نوبتی مطابق فیلتر انتخابی وجود ندارد.'}}</td></tr></tbody></table></div></div><div v-if="editing" class="fixed inset-0 z-50 bg-[#09251f]/50 flex items-center justify-center p-4" @click.self="editing=null"><div class="bg-white p-7 rounded-3xl shadow-soft max-w-lg w-full max-h-[90vh] overflow-y-auto"><div class="flex justify-between items-center mb-6"><h3 class="font-extrabold">جابه‌جایی نوبت {{editing.patient_name}}</h3><button @click="editing=null"><Icon name="x" /></button></div><label class="field-label">تاریخ جدید (شمسی)</label><JalaliCalendar v-model="newDate" :horizon="365" /><label class="field-label mt-5">ساعت جدید (مثلاً 10:30)</label><input v-model="newTime" class="input-field" dir="ltr" placeholder="10:30" /><p class="text-[11px] leading-6 text-[#8ba296] mt-2">تغییر زمان پس از بررسی ساعت‌های آزاد و تداخل با دیگر نوبت‌ها انجام می‌شود.</p><button class="btn-main mt-6" :disabled="working" @click="saveTime">ثبت جابه‌جایی</button></div></div></div></template>
